"use client"

/**
 * Metric Sparkline (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/metric-sparkline
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { NumberFlow } from "@/lib/notchset/number-flow"
import { useSound } from "@/lib/notchset/sound"
import { isRtl } from "@/lib/notchset/shared"

/*
 * Metric Sparkline: a number, its change and a small area chart. Switching range morphs the same thirty
 * points into the new shape; dragging (or the arrow keys) scrubs along the line, ticking at each point,
 * and the number and change follow the point you're on.
 */

interface SparkRange {
  id: string
  label: string
  /** The values for this range, oldest first (resampled to 30 points). */
  values: readonly number[]
  /** Days per point, for the "Nd ago" line. */
  daysPerPoint?: number | undefined
}

interface MetricSparklineProps extends Omit<React.ComponentPropsWithoutRef<"div">, "onChange"> {
  label: string
  ranges: readonly SparkRange[]
  defaultRange?: string | undefined
  format?: ((n: number) => string) | undefined
  sound?: boolean | undefined
}

const POINTS = 30
const W = 300
const H = 96

/** The series resampled to POINTS evenly spaced values. */
function resample(values: readonly number[]) {
  const src = values.filter((v) => Number.isFinite(v))
  if (src.length === 0) return Array.from({ length: POINTS }, () => 0)
  if (src.length === 1) return Array.from({ length: POINTS }, () => src[0]!)
  return Array.from({ length: POINTS }, (_, i) => {
    const t = (i / (POINTS - 1)) * (src.length - 1)
    const a = Math.floor(t)
    const b = Math.min(src.length - 1, a + 1)
    return src[a]! + (src[b]! - src[a]!) * (t - a)
  })
}

const MetricSparkline = React.forwardRef<HTMLDivElement, MetricSparklineProps>(function MetricSparkline(
  { label, ranges, defaultRange, format = (n) => Math.round(n).toLocaleString(), sound = true, className, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const [rangeId, setRangeId] = React.useState(defaultRange ?? ranges[0]?.id ?? "")
  const [scrub, setScrub] = React.useState<number | null>(null)
  const range = ranges.find((r) => r.id === rangeId) ?? ranges[0]
  const series = resample(range?.values ?? [])
  const min = Math.min(...series)
  const max = Math.max(...series)
  const span = max - min || 1
  const x = (i: number) => (i / (POINTS - 1)) * W
  const y = (v: number) => H - 6 - ((v - min) / span) * (H - 16)
  const line = series.map((v, i) => `${i ? "L" : "M"}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(" ")
  const area = `${line} L${W} ${H} L0 ${H} Z`
  const point = scrub ?? POINTS - 1
  const first = series[0] ?? 0
  const delta = first ? ((series[point]! - first) / Math.abs(first)) * 100 : 0
  const thumbIndex = Math.max(0, ranges.findIndex((r) => r.id === rangeId))
  const days = Math.round((POINTS - 1 - point) * (range?.daysPerPoint ?? 1))

  const scrubTo = (i: number) => {
    const next = Math.max(0, Math.min(POINTS - 1, i))
    if (next !== scrub) sfx.scrub(next)
    setScrub(next)
  }
  const fromPointer = (event: React.PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect()
    const k = (event.clientX - box.left) / box.width
    scrubTo(Math.round((isRtl(event.currentTarget as Element) ? 1 - k : k) * (POINTS - 1)))
  }

  return (
    <div ref={ref} data-slot="metric-sparkline" data-notchset="" className={cn("flex w-full flex-col gap-3", className)} {...props}>
      <div className="flex items-start justify-between gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="text-[length:var(--ns-type-copy)] font-medium text-[var(--foreground)]">{label}</span>
          <span className="flex items-center gap-2">
            <span className="font-mono text-[30px] leading-9 font-medium tracking-[-0.03em] text-[var(--foreground)] tabular-nums"><NumberFlow value={format(series[point] ?? 0)} /></span>
            <span
              className={cn(
                "rounded-[var(--radius)] px-2 py-0.5 font-mono text-[11px] font-medium whitespace-nowrap",
                delta >= 0
                  ? "bg-[color-mix(in_oklab,var(--success,var(--foreground))_14%,transparent)] text-[color-mix(in_oklab,var(--success,var(--foreground))_72%,var(--foreground))]"
                  : "bg-[color-mix(in_oklab,var(--destructive)_14%,transparent)] text-[color-mix(in_oklab,var(--destructive)_72%,var(--foreground))]"
              )}
            >
              {delta >= 0 ? "+" : "−"}
              {Math.abs(delta).toFixed(1)}%
            </span>
          </span>
        </div>
        <div role="radiogroup" aria-label="Range" className="relative flex rounded-[var(--radius)] bg-[var(--muted)] p-0.5">
          <span aria-hidden="true" className="absolute inset-y-0.5 w-10 rounded-[max(calc(var(--radius)-2px),4px)] bg-[var(--background)] shadow-[0_1px_2px_rgba(0,0,0,.08)] [transition:inset-inline-start_.45s_cubic-bezier(.2,1.25,.3,1)]" style={{ insetInlineStart: 2 + thumbIndex * 40 }} />
          {ranges.map((r) => (
            <button
              key={r.id}
              type="button"
              role="radio"
              aria-checked={r.id === rangeId}
              onClick={() => {
                if (r.id === rangeId) return
                sfx.tick()
                setScrub(null)
                setRangeId(r.id)
              }}
              className={cn(
                "relative h-7 w-10 cursor-pointer rounded-[max(calc(var(--radius)-2px),4px)] font-mono text-[11px] outline-none [transition:color_.2s] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]",
                r.id === rangeId ? "text-[var(--foreground)]" : "text-[color-mix(in_oklab,var(--muted-foreground)_80%,var(--foreground))]"
              )}
            >
              {r.label}
            </button>
          ))}
        </div>
      </div>
      <div
        role="slider"
        tabIndex={0}
        aria-label={`${label}, ${range?.label ?? ""}`}
        aria-valuemin={0}
        aria-valuemax={POINTS - 1}
        aria-valuenow={point}
        aria-valuetext={`${format(series[point] ?? 0)}${days ? `, ${days} days ago` : ", today"}`}
        onPointerDown={fromPointer}
        onPointerMove={fromPointer}
        onPointerLeave={() => setScrub(null)}
        onKeyDown={(event) => {
          if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return
          event.preventDefault()
          const forward = (event.key === "ArrowRight") !== (isRtl(event.currentTarget as Element))
          scrubTo(point + (forward ? 1 : -1))
        }}
        onBlur={() => setScrub(null)}
        className="relative h-24 cursor-crosshair touch-none rounded-[min(var(--radius),8px)] outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
      >
        <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true" className="absolute inset-0 size-full overflow-visible rtl:-scale-x-100">
          <path d={area} className="fill-[color-mix(in_oklab,var(--info,var(--foreground))_12%,transparent)] [transition:d_.7s_var(--ns-ease-settle)]" />
          <path d={line} fill="none" strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinejoin="round" className="stroke-[var(--info,var(--foreground))] [transition:d_.7s_var(--ns-ease-settle)]" />
        </svg>
        {scrub != null && (
          <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 w-px bg-[var(--border)] rtl:translate-x-px" style={{ insetInlineStart: `${(scrub / (POINTS - 1)) * 100}%` }}>
            <span className="absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-[var(--background)] shadow-[0_0_0_2.5px_var(--info,var(--foreground))] rtl:translate-x-1/2" style={{ top: `${(y(series[scrub]!) / H) * 100}%` }} />
          </span>
        )}
      </div>
      <div className="flex justify-between font-mono text-[11px] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">
        <span>{scrub == null ? "drag to scrub" : days ? `${days}d ago` : "today"}</span>
        <span>{range?.label}</span>
      </div>
      <table className="sr-only">
        <caption>{label}</caption>
        <tbody>
          {series.map((v, i) => (
            <tr key={i}>
              <td>{Math.round((POINTS - 1 - i) * (range?.daysPerPoint ?? 1))} days ago</td>
              <td>{format(v)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
})

export { MetricSparkline, type MetricSparklineProps, type SparkRange }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { DrawCheck } from "@/lib/notchset/shared"
import type { Sfx } from "@/lib/notchset/sound"

/*
 * Progress parts: milestone sounds (progress is silent while it waits and speaks only at each
 * tenth and on completion), the ring, the check badge that pops in, and a photo avatar with an
 * initials fallback. Changing numbers roll through NumberFlow (lib/number-flow.tsx).
 */

/** Clamps a 0–100 value (non-finite becomes 0). */
const pct = (value: number) => (Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0)

/** Plays a decile tick each time progress crosses a tenth, and a chime when it completes. */
function useMilestones(value: number, done: boolean, sfx: Sfx) {
  const decile = React.useRef(Math.floor(pct(value) / 10))
  const wasDone = React.useRef(done)
  React.useEffect(() => {
    const d = Math.floor(pct(value) / 10)
    if (d > decile.current && d < 10) sfx.decile(d)
    decile.current = d
  }, [value, sfx])
  React.useEffect(() => {
    if (done && !wasDone.current) sfx.chime()
    wasDone.current = done
  }, [done, sfx])
}

/** A progress ring: `value` 0–1, the arc in `className`'s stroke colour over a muted track. */
function Ring({ value, size = 22, stroke = 2.5, className, trackClassName }: { value: number; size?: number | undefined; stroke?: number | undefined; className?: string | undefined; trackClassName?: string | undefined }) {
  const r = (size - stroke) / 2
  return (
    <svg viewBox={`0 0 ${size} ${size}`} aria-hidden="true" className="shrink-0 -rotate-90" style={{ width: size, height: size }}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={stroke} className={cn("stroke-[var(--muted)]", trackClassName)} />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        strokeWidth={stroke}
        strokeLinecap="round"
        pathLength={1}
        className={cn("stroke-[var(--info,var(--foreground))] [stroke-dasharray:1] [transition:stroke-dashoffset_.3s_linear,stroke_.3s]", className)}
        style={{ strokeDashoffset: 1 - Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0)) }}
      />
    </svg>
  )
}

/** A green circle whose check draws in, popping from .4 to full size. */
function CheckBadge({ shown, size = 22, className }: { shown: boolean; size?: number | undefined; className?: string | undefined }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "grid shrink-0 place-items-center rounded-full bg-[var(--success,var(--foreground))] text-[var(--success-foreground,var(--background))] [transition:transform_.45s_cubic-bezier(.2,1.7,.4,1),scale_.45s_cubic-bezier(.2,1.7,.4,1),translate_.45s_cubic-bezier(.2,1.7,.4,1),rotate_.45s_cubic-bezier(.2,1.7,.4,1),opacity_.2s]",
        shown ? "scale-100 opacity-100" : "scale-[.4] opacity-0",
        className
      )}
      style={{ width: size, height: size }}
    >
      <DrawCheck shown={shown} className="size-[55%]" />
    </span>
  )
}

/** A person's photo (as a background, so a dead URL never shows a broken image) over their initials. */
function Avatar({ src, name, size = 32, className }: { src?: string | undefined; name: string; size?: number | undefined; className?: string | undefined }) {
  const initials = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("")
  return (
    <span
      role="img"
      aria-label={name}
      data-slot="avatar"
      className={cn("relative grid shrink-0 place-items-center overflow-hidden rounded-full bg-[var(--muted)] text-[color-mix(in_oklab,var(--muted-foreground)_80%,var(--foreground))] shadow-[0_0_0_1px_var(--border)]", className)}
      style={{ width: size, height: size, fontSize: Math.round(size * 0.36) }}
    >
      <span aria-hidden="true" className="font-medium">
        {initials}
      </span>
      {/* The photo covers the initials; if it fails to load the initials show through. */}
      {src && <span aria-hidden="true" className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url("${src}")` }} />}
    </span>
  )
}

export { Avatar, CheckBadge, pct, Ring, useMilestones }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * NumberFlow: the fluid number every changing figure renders through (countdowns, times, counts, totals).
 * Each digit is its own 0–9 column that springs to the new digit with a slight motion blur; digits that
 * appear or disappear animate their width, so the text never jumps. Other characters (":", ",", " ")
 * swap in place. Screen readers get the plain value.
 */

const H = 1.15 // em, one digit row

function Digit({ d, enter, tight }: { d: number; enter: boolean; tight?: boolean | undefined }) {
  // Each change flips between two identical blur keyframes, so the blur restarts every time.
  const [seen, setSeen] = React.useState(d)
  const [flips, setFlips] = React.useState(0)
  if (seen !== d) {
    setSeen(d)
    setFlips((n) => n + 1)
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative inline-block [clip-path:inset(0_-0.15em)]",
        // Tight digits are narrower than their glyphs: they clip only up and down (the clip-path bounds the sides), so a 1 isn't cut.
        tight ? "[overflow-x:visible] [overflow-y:clip] transition-[width] duration-[.55s] ease-[var(--ns-ease-settle)] motion-reduce:transition-none" : "w-[1ch] overflow-hidden",
        enter && "animate-[ns-num-in_.55s_var(--ns-ease-settle)_both] motion-reduce:animate-none"
      )}
      // Tight digits: a 1 is narrower than the rest, as in a headline price.
      style={{ height: `${H}em`, lineHeight: `${H}em`, width: tight ? (d === 1 ? "0.43em" : "0.58em") : undefined }}
    >
      <span
        className={cn(
          "flex flex-col",
          // Tight: each glyph keeps a box as wide as itself, centred in the narrower slot.
          tight && "items-center",
          "[transition:transform_.85s_var(--ns-ease-settle),scale_.85s_var(--ns-ease-settle),translate_.85s_var(--ns-ease-settle),rotate_.85s_var(--ns-ease-settle)] motion-reduce:transition-none",
          flips > 0 && (flips % 2 ? "animate-[ns-num-blur_.45s_ease-out]" : "animate-[ns-num-blur-b_.45s_ease-out]")
        )}
        style={{ transform: `translateY(${-d * H}em)` }}
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span key={i} className={cn("block text-center", tight && "w-[0.76em] shrink-0")} style={{ height: `${H}em` }}>
            {i}
          </span>
        ))}
      </span>
    </span>
  )
}

interface NumberFlowProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The value as it should read, e.g. 42, "09:30" or "1,204". */
  value: string | number
  /** Proportional digit widths (a 1 is 0.43em, the rest 0.58em), for large headline figures. */
  tight?: boolean | undefined
}

const NumberFlow = React.forwardRef<HTMLSpanElement, NumberFlowProps>(function NumberFlow({ value, tight, className, ...props }, ref) {
  const text = String(value)
  const chars = Array.from(text)
  // Positions are counted from the right, so the ones digit stays the ones digit when the length changes.
  const [initialLength] = React.useState(chars.length)
  const [prev, setPrev] = React.useState(text)
  const [leaving, setLeaving] = React.useState<{ id: string; ch: string }[]>([])
  if (prev !== text) {
    const old = Array.from(prev)
    if (old.length > chars.length) {
      const gone = old.slice(0, old.length - chars.length).filter((ch) => ch >= "0" && ch <= "9")
      setLeaving((l) => [...l, ...gone.map((ch, i) => ({ id: `${prev}>${text}:${i}`, ch }))].slice(-4))
    }
    setPrev(text)
  }

  return (
    <span ref={ref} data-slot="number-flow" className={cn("inline-flex whitespace-nowrap tabular-nums", className)} {...props}>
      <span className="sr-only">{text}</span>
      {leaving.map((g) => (
        <span
          key={`out-${g.id}`}
          aria-hidden="true"
          className="inline-block w-0 animate-[ns-num-out_.45s_var(--ns-ease-settle)_both] overflow-hidden text-center"
          style={{ height: `${H}em`, lineHeight: `${H}em` }}
          onAnimationEnd={() => setLeaving((l) => l.filter((x) => x.id !== g.id))}
        >
          {g.ch}
        </span>
      ))}
      {chars.map((ch, i) => {
        const pos = chars.length - i
        return ch >= "0" && ch <= "9" ? (
          <Digit key={`d${pos}`} d={Number(ch)} enter={pos > initialLength} tight={tight} />
        ) : (
          <span key={`s${pos}`} aria-hidden="true" className="inline-block whitespace-pre" style={{ height: `${H}em`, lineHeight: `${H}em` }}>
            {ch}
          </span>
        )
      })}
    </span>
  )
})

export { NumberFlow, type NumberFlowProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
        className="[stroke-dasharray:24] transition-[stroke-dashoffset] delay-150 duration-[450ms] ease-[cubic-bezier(.6,0,.2,1)] motion-reduce:transition-none"
        style={{ strokeDashoffset: shown ? 0 : 24 }}
      />
    </svg>
  )
}

/** The 14px spinner: an arc turning every .7s. */
function Spinner({ className }: { className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 shrink-0 animate-[ns-spin_.7s_linear_infinite]", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" className="[stroke-dasharray:20_40]" />
    </svg>
  )
}

/** A 7px dot with a ring that keeps blooming out of it (live). */
function LiveDot({ className }: { className?: string | undefined }) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex size-[7px] shrink-0", className)}>
      <span className="absolute inset-0 animate-[ns-live_1.2s_ease-out_infinite] rounded-full bg-current" />
      <span className="relative size-full rounded-full bg-current" />
    </span>
  )
}

/**
