  const enabled = Boolean(React.useContext(SoundContext)?.enabled) && sound
  return React.useMemo(() => ({ sfx: enabled ? SFX : SILENT, holdTone: enabled ? startHoldTone : () => ({ stop() {} }) }), [enabled])
}

